    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: A 60-year-old male presents with "Crushing" substernal chest pain radiating to the left arm. Which diagnosis has the highest pre-test probability?', '["Pulmonary Embolism", "Acute Coronary Syndrome (ACS)", "Aortic Dissection", "Gastroesophageal Reflux"]', 1, 'Radiating crushing pain in an older male is the classic "Representativeness" for ACS.'),
    (v_topic_id, '102: "Pleuritic" chest pain (worsened by deep breathing or coughing) suggests inflammation of the:', '["Myocardium", "Pleura or Pericardium", "Esophagus", "Stomach"]', 1, 'Classic causes include pneumonia, PE, or pericarditis.'),
    (v_topic_id, '103: Chest pain that is "Tearing" and radiates to the BACK is most suggestive of:', '["Myocardial Infarction", "Aortic Dissection", "Tension Pneumothorax", "Pancreatitis"]', 1, 'Radiological confirmation with CT-A or TEE is urgently required.'),
    (v_topic_id, '104: A patient with "Chest Pain" and "Tenderness to palpation" over the costochondral junctions likely has:', '["Acute MI", "Costochondritis", "Pneumonia", "Pulmonary Embolism"]', 1, 'Reproducible chest wall tenderness has a very low Likelihood Ratio for ACS.'),
    (v_topic_id, '105: "Dyspnea" that is sudden in onset (within seconds to minutes) should prompt immediate consideration of:', '["COPD exacerbation", "Pneumothorax or Pulmonary Embolism", "Pneumonia", "Lung cancer"]', 1, 'Sudden onset suggests a "mechanical" or "vascular" event.'),
    (v_topic_id, '106: "Orthopnea" (dyspnea when lying flat) and "Paroxysmal Nocturnal Dyspnea" (PND) are high-yield signs of:', '["Asthma", "Congestive Heart Failure (Left-sided)", "Anemia", "Liver failure"]', 1, 'They represent redistribution of fluid to the lungs when recumbent.'),
    (v_topic_id, '107: A "Productive" cough with "Rusty" colored sputum is classically associated with:', '["Klebsiella pneumonia", "Streptococcus pneumoniae", "Mycoplasma", "Lung abscess"]', 1, 'Rusty sputum is a "Representation" of pneumococcal pneumonia.'),
    (v_topic_id, '108: A "Productive" cough with "Currant Jelly" sputum is classically associated with:', '["Klebsiella pneumoniae", "Strep pneumoniae", "Viral flu", "Tuberculosis"]', 0, 'Often seen in patients with alcoholism or chronic lung disease.'),
    (v_topic_id, '109: "Hemoptysis" (coughing up blood) in a young smoker with a history of travel should prompt evaluation for:', '["Heart failure", "Tuberculosis or Pulmonary Embolism", "Asthma", "Bronchitis"]', 1, 'PE (from DVT after travel) and TB are critical differentials.'),
    (v_topic_id, '110: "Syncope" during exertion (e.g., exercise) is a "Red Flag" for:', '["Vasovagal syncope", "Aortic Stenosis or Hypertrophic Cardiomyopathy", "Hypoglycemia", "Dehydration"]', 1, 'Exertional syncope suggests an inability to increase cardiac output in response to demand.'),
    (v_topic_id, '111: A patient who feels faint after seeing blood or during prolonged standing likely has:', '["Cardiac arrhythmia", "Vasovagal Syncope (Neurocardiogenic)", "Stroke", "Seizure"]', 1, 'Triggered by a reflex increase in vagal tone and withdrawal of sympathetic tone.'),
    (v_topic_id, '112: "Palpitations" that feel like a "Flip-flopping" in the chest are often due to:', '["Atrial Fibrillation", "Premature Ventricular Contractions (PVCs) or PACs", "SVT", "Heart block"]', 1, 'The sensation often comes from the forceful beat following a compensatory pause.'),
    (v_topic_id, '113: "Chest Pain" relieved by sitting forward is characteristic of:', '["MI", "Pericarditis", "Aortic Dissection", "Esophagitis"]', 1, 'The leaning forward position reduces friction between the inflamed pericardial layers.'),
    (v_topic_id, '114: A "Widened Mediastinum" on CXR in a patient with severe chest pain is a high-yield clue for:', '["Pneumonia", "Aortic Dissection", "Pneumothorax", "PE"]', 1, 'Mediastinal hematoma or aortic dilatation.'),
    (v_topic_id, '115: "Hamman''s Sign" (crunching sound heard over the heart during systole) indicates:', '["Pericarditis", "Pneumomediastinum (air in the mediastinum)", "Murmur", "Pleural effusion"]', 1, 'Often seen after esophageal rupture (Boerhaave) or trauma.'),
    (v_topic_id, '116: The "Well''s Criteria" are used to estimate the pre-test probability of:', '["Heart failure", "Pulmonary Embolism or DVT", "Pneumonia", "Stroke"]', 1, 'It helps decide whether to order a D-dimer (low risk) or go straight to imaging (high risk).'),
    (v_topic_id, '117: "Platypnea" (dyspnea that worsens when upright and improves when lying flat) is seen in:', '["Heart failure", "Hepatopulmonary Syndrome or PFO/ASD", "COPD", "Asthma"]', 1, 'Orthodeoxia (dropping O2 saturation when upright) often accompanies it.'),
    (v_topic_id, '118: "Trepopnea" (dyspnea that occurs when lying on one side but not the other) indicates:', '["Heart failure", "Unilateral lung disease or pleural effusion", "Anxiety", "Obesity"]', 1, 'Patients prefer to lie with the "good" lung down to improve V/Q matching, or sometimes "bad" lung down depending on the pathology.'),
    (v_topic_id, '119: A "Bovine" cough (lacking the normal explosive start) suggests:', '["Asthma", "Recurrent Laryngeal Nerve Palsy (vocal cord paralysis)", "Pneumonia", "Smoking"]', 1, 'The patient cannot effectively close the glottis to build up pressure.'),
    (v_topic_id, '120: "Wheezing" that is localized to ONE area of the lung is highly concerning for:', '["Asthma exacerbation", "Foreign body aspiration or Bronchogenic carcinoma", "CHF", "COPD"]', 1, 'Generalized wheezing suggests diffuse airway disease; focal wheezing suggests an obstruction.'),
    (v_topic_id, '121: "Stridor" is a high-pitched inspiratory sound indicating:', '["Lower airway obstruction", "Upper airway obstruction (emergency)", "Pleural inflammation", "Heart failure"]', 1, 'Requires immediate assessment for airway patency.'),
    (v_topic_id, '122: "Chest Pain" that is worsened by eating a large meal and occurs when lying down is likely:', '["Angina", "GERD (Gastroesophageal Reflux)", "PE", "Pericarditis"]', 1, 'Often relieved by antacids or upright positioning.'),
    (v_topic_id, '123: "Levine''s Sign" is a clinical gesture where the patient:', '["Points to their back", "Clenches their fist over their chest (suggesting ischemic pain)", "Leans forward", "Coughs"]', 1, 'A classic behavioral marker for angina.'),
    (v_topic_id, '124: "Angina" that occurs at rest and shows transient ST elevation on ECG is known as:', '["Unstable Angina", "Prinzmetal (Variant) Angina", "NSTEMI", "Silent Ischemia"]', 1, 'Caused by coronary artery vasospasm.'),
    (v_topic_id, '125: "Dyspnea" + "Pleuritic Chest Pain" + "Hemoptysis" is the classic triad (though rare) for:', '["Pneumonia", "Pulmonary Embolism", "Lung cancer", "Asthma"]', 1, 'Also look for risk factors like recent surgery or prolonged immobility.'),
    (v_topic_id, '126: A patient with "Acute Chest Pain" and "Cold, Pulseless legs" likely has:', '["MI", "Aortic Dissection extending into the iliacs", "PE", "Heart failure"]', 1, 'Dissection can shear off the ostia of major branches, causing ischemia in distant organs.'),
    (v_topic_id, '127: "Cough" following the initiation of an "ACE Inhibitor" is due to:', '["Infection", "Bradykinin accumulation", "Heart failure", "Allergy"]', 1, 'Switching to an ARB usually resolves the cough.'),
    (v_topic_id, '128: "Chronic Cough" is defined as a cough lasting more than:', '["1 week", "2 weeks", "8 weeks", "6 months"]', 2, 'Top 3 causes in non-smokers: Post-nasal drip, Asthma, and GERD.'),
    (v_topic_id, '129: "Syncope" following a "Coughing fit" or "Urination" is:', '["Cardiac", "Situational Syncope (a form of reflex syncope)", "Epilepsy", "Stroke"]', 1, 'Increased intrathoracic pressure or vagal stimulation leads to a transient drop in BP.'),
    (v_topic_id, '130: "Palpitations" associated with "Weight loss," "Heat intolerance," and "Tremor" suggest:', '["Heart failure", "Hyperthyroidism", "Diabetes", "Anxiety"]', 1, 'Excess thyroid hormone increases cardiac sensitivity to catecholamines.'),
    (v_topic_id, '131: "Chest Pain" in a 20-year-old female with "Mid-systolic click" and "Late-systolic murmur" is:', '["MI", "Mitral Valve Prolapse (MVP)", "Aortic Stenosis", "Normal"]', 1, 'MVP is a common benign cause of atypical chest pain in young women.'),
    (v_topic_id, '132: "Kussmaul''s Sign" (increase in JVP on inspiration) is a sign of:', '["Heart failure", "Constrictive Pericarditis or Right Ventricular MI", "Asthma", "Pneumonia"]', 1, 'The right heart cannot accommodate the increased venous return during inspiration.'),
    (v_topic_id, '133: "Pulsus Paradoxus" (drop in systolic BP > 10 mmHg on inspiration) is a hallmark of:', '["Aortic Stenosis", "Cardiac Tamponade", "MI", "Hypertension"]', 1, 'Also seen in severe asthma and COPD.'),
    (v_topic_id, '134: A patient with "Fever," "New Heart Murmur," and "Splinter Hemorrhages" likely has:', '["Pneumonia", "Infective Endocarditis", "Rheumatic Fever", "Sepsis"]', 1, 'Vegetations on valves can embolize or cause valvular dysfunction.'),
    (v_topic_id, '135: "Subclavian Steal Syndrome" presents with syncope and _____:', '["Leg pain", "Difference in blood pressure between arms (> 15 mmHg)", "Headache", "Rash"]', 1, 'Blood is "stolen" from the vertebral artery to supply the arm during exertion.'),
    (v_topic_id, '136: "Hoarseness" of voice in a patient with a "Large Left Atrium" (e.g., from Mitral Stenosis) is called:', '["Boerhaave syndrome", "Ortner''s Syndrome", "Horner syndrome", "Croup"]', 1, 'The enlarged atrium compresses the left recurrent laryngeal nerve.'),
    (v_topic_id, '137: "Pink, Frothy Sputum" is a classic sign of:', '["Pneumonia", "Acute Pulmonary Edema (CHF)", "Tuberculosis", "Lung cancer"]', 1, 'Alveolar capillaries rupture under high pressure, leaking RBCs and fluid.'),
    (v_topic_id, '138: "Clubbing" of the fingers in a smoker with a chronic cough should prompt evaluation for:', '["COPD", "Lung Cancer (especially non-small cell)", "Asthma", "Bronchitis"]', 1, 'Clubbing is NOT typically seen in uncomplicated COPD.'),
    (v_topic_id, '139: "Dyspnea" + "History of Asbestos exposure" 30 years ago suggests:', '["Asthma", "Mesothelioma or Lung Cancer", "Pneumonia", "Emphysema"]', 1, 'Asbestos-related diseases have a long latency period.'),
    (v_topic_id, '140: "Palpitations" that can be stopped by "Carotid Sinus Massage" or "Valsalva" are likely:', '["Atrial Fibrillation", "Supraventricular Tachycardia (SVT)", "Ventricular Tachycardia", "Sinus Tachycardia"]', 1, 'These maneuvers increase vagal tone and slow AV node conduction.'),
    (v_topic_id, '141: A "Mid-diastolic Rumble" heard at the apex suggests:', '["Aortic Stenosis", "Mitral Stenosis", "Mitral Regurgitation", "Tricuspid Regurgitation"]', 1, 'Often preceded by an "Opening Snap."'),
    (v_topic_id, '142: A "Holosystolic Murmur" heard best at the apex and radiating to the axilla is:', '["Mitral Regurgitation", "Aortic Stenosis", "VSD", "Tricuspid Regurgitation"]', 0, 'Usually louder with maneuvers that increase afterload (e.g., handgrip).'),
    (v_topic_id, '143: A "Crescendo-Decrescendo" systolic murmur heard at the 2nd right intercostal space is:', '["Mitral Regurgitation", "Aortic Stenosis", "ASD", "Pulmonary Stenosis"]', 1, 'Radiates to the carotids.'),
    (v_topic_id, '144: A "Diastolic Decrescendo" murmur heard at the left sternal border is:', '["Mitral Stenosis", "Aortic Regurgitation", "Tricuspid Stenosis", "VSD"]', 1, 'Best heard with the patient leaning forward and exhaling.'),
    (v_topic_id, '145: "Chest Pain" in a patient who recently had a "Viral illness" and now has an "ECG with diffuse ST elevation" is:', '["Acute MI", "Acute Pericarditis", "PE", "Dissection"]', 1, 'ST elevation is concave-upwards and involves almost all leads.'),
    (v_topic_id, '146: "Chest Pain" that occurs predictably with exertion and is relieved by 5 minutes of rest is:', '["Unstable Angina", "Stable Angina", "MI", "Costochondritis"]', 1, 'Matches the "Representativeness" for stable CAD.'),
    (v_topic_id, '147: "Syncope" while "Shaving" or wearing a "Tight collar" is:', '["Vasovagal", "Carotid Sinus Hypersensitivity", "Stroke", "Seizure"]', 1, 'Pressure on the carotid sinus triggers an exaggerated baroreceptor reflex.'),
    (v_topic_id, '148: "Leg Pain" that occurs with walking and is relieved by rest (Claudication) is a marker for:', '["Venous Insufficiency", "Peripheral Artery Disease (PAD)", "DVT", "Cellulitis"]', 1, 'Indicates significant systemic atherosclerosis.'),
    (v_topic_id, '149: A "Bilateral Hilar Lymphadenopathy" on CXR in a patient with a dry cough is:', '["Tuberculosis", "Sarcoidosis", "Lung cancer", "Pneumonia"]', 1, 'Often seen in young adults; can also present with erythema nodosum.'),
    (v_topic_id, '150: "Night Sweats" and "Weight Loss" in a patient with a chronic cough are "B-symptoms" of:', '["Asthma", "Tuberculosis or Lymphoma", "Diabetes", "COPD"]', 1, 'Suggests a chronic infectious or malignant process.'),
    (v_topic_id, '151: "Dyspnea" and "Hyper-resonant lungs" with "Decreased breath sounds" on one side is:', '["Pneumonia", "Pneumothorax", "Pleural Effusion", "Lung cancer"]', 1, 'Air in the pleural space makes the lung collapse and the chest sound hollow.'),
    (v_topic_id, '152: "Dyspnea" and "Dullness to percussion" with "Decreased breath sounds" on one side is:', '["Pneumothorax", "Pleural Effusion", "Emphysema", "Asthma"]', 1, 'Fluid in the pleural space acts as a muffler.'),
    (v_topic_id, '153: "Dyspnea" and "Increased tactile fremitus" with "Dullness to percussion" is:', '["Pneumothorax", "Consolidation (Pneumonia)", "Pleural effusion", "COPD"]', 1, 'Solid/fluid-filled lung tissue conducts sound/vibration better than air-filled tissue.'),
    (v_topic_id, '154: A "Systolic Murmur" that gets LOUDER with "Valsalva" (decreased preload) is characteristic of:', '["Aortic Stenosis", "Hypertrophic Obstructive Cardiomyopathy (HOCM)", "Mitral Regurgitation", "MVP"]', 1, 'Decreased blood in the ventricle allows the septum and valve to obstruct the outlet more.'),
    (v_topic_id, '155: A "Systolic Murmur" that gets QUIETER with "Squatting" (increased preload/afterload) is:', '["Aortic Stenosis", "HOCM", "VSD", "Mitral Regurgitation"]', 1, 'Increased ventricular volume "stretches" the outlet open.'),
    (v_topic_id, '156: "Dyspnea" that is severe and out of proportion to physical exam findings in a patient with a DVT is:', '["Asthma", "Pulmonary Embolism", "Pneumonia", "Anxiety"]', 1, 'The lungs may sound clear because the problem is in the vessels, not the airways.'),
    (v_topic_id, '157: "Chest Pain" + "Syncope" + "Dyspnea" is the classic triad for:', '["Mitral Stenosis", "Aortic Stenosis", "MI", "PE"]', 1, 'Mnemonic: SAD (Syncope, Angina, Dyspnea).'),
    (v_topic_id, '158: "Jugular Venous Distension" (JVD) with "Clear Lungs" suggests:', '["Left-sided Heart Failure", "Right-sided Heart Failure or PE", "Pneumonia", "Asthma"]', 1, 'If the lungs were the cause (left heart failure), they would have crackles.'),
    (v_topic_id, '159: "Hepatomegaly" and "Peripheral Edema" are signs of:', '["Left heart failure", "Right heart failure", "Pneumonia", "Stroke"]', 1, 'Back-up of blood into the systemic venous circulation.'),
    (v_topic_id, '160: A "Machine-like" continuous murmur heard best below the left clavicle is:', '["Aortic Stenosis", "Patent Ductus Arteriosus (PDA)", "VSD", "ASD"]', 1, 'Heard throughout both systole and diastole.'),
    (v_topic_id, '161: "Chest Pain" in a 70-year-old with a history of HTN and smoking is a "Horses, not Zebras" case for:', '["Anxiety", "Acute Coronary Syndrome", "Boerhaave syndrome", "Esophageal spasm"]', 1, 'The prevalence of CAD in this population is very high.'),
    (v_topic_id, '162: "Dyspnea" in a patient with "Symmetric, pitting edema" of both legs is most likely:', '["DVT", "Congestive Heart Failure", "Cellulitis", "Trauma"]', 1, 'Bilateral edema suggests a systemic cause like heart, liver, or kidney failure.'),
    (v_topic_id, '163: "Unilateral leg swelling" and "Pain" after a long flight is:', '["Heart failure", "Deep Vein Thrombosis (DVT)", "Cellulitis", "Lymphedema"]', 1, 'Virchow''s triad: Stasis, Hypercoagulability, and Endothelial injury.'),
    (v_topic_id, '164: "Chest Pain" + "Nausea/Vomiting" + "Diaphoresis (Sweating)" is highly suggestive of:', '["GERD", "Myocardial Infarction", "Pneumonia", "Panic attack"]', 1, 'These are signs of sympathetic activation during an MI.'),
    (v_topic_id, '165: A "Low-pitched" S3 gallop is a sign of:', '["Ventricular Filling into a dilated, compliant ventricle (Volume Overload)", "Stiff ventricle", "Normal heart", "Murmur"]', 0, 'Associated with Systolic Heart Failure.'),
    (v_topic_id, '166: A "Low-pitched" S4 gallop is a sign of:', '["Volume overload", "Atrial contraction into a stiff, non-compliant ventricle (Pressure Overload)", "Normal aging", "Mitral stenosis"]', 1, 'Associated with Diastolic Heart Failure (HTN, LVH).'),
    (v_topic_id, '167: "Click" heard during mid-systole followed by a crescendo murmur is:', '["Aortic Stenosis", "Mitral Valve Prolapse", "ASD", "Mitral Stenosis"]', 1, 'The click is the tensing of the chordae tendineae.'),
    (v_topic_id, '168: "Opening Snap" followed by a diastolic rumble is:', '["Aortic Regurgitation", "Mitral Stenosis", "Tricuspid Regurgitation", "ASD"]', 1, 'The snap is the stenotic mitral valve opening under pressure.'),
    (v_topic_id, '169: "Water-hammer pulse" (Corrigan pulse) is a rapid upstroke and collapse of the pulse seen in:', '["Aortic Stenosis", "Aortic Regurgitation", "Mitral Regurgitation", "Heart failure"]', 1, 'Due to a large stroke volume and rapid backflow into the LV.'),
    (v_topic_id, '170: "Pulsus Alternans" (alternating strong and weak pulses) is a sign of:', '["Severe Left Ventricular Systolic Dysfunction", "Tamponade", "Normal heart", "Arrhythmia"]', 0, 'It indicates a failing heart.'),
    (v_topic_id, '171: "Wide Fixed Splitting" of the S2 sound is the classic sign of:', '["Aortic Stenosis", "Atrial Septal Defect (ASD)", "VSD", "Mitral Regurgitation"]', 1, 'The split does not change with respiration.'),
    (v_topic_id, '172: "Paradoxical Splitting" of S2 (split on expiration, not inspiration) is seen in:', '["Right Bundle Branch Block", "Left Bundle Branch Block or Aortic Stenosis", "Normal heart", "ASD"]', 1, 'Closure of the aortic valve is delayed past the closure of the pulmonic valve.'),
    (v_topic_id, '173: "Dyspnea" + "Harsh holosystolic murmur at the left sternal border" in a newborn is:', '["ASD", "Ventricular Septal Defect (VSD)", "PDA", "ToF"]', 1, 'VSD is the most common congenital heart defect.'),
    (v_topic_id, '174: "Cyanosis" (bluish skin) that does not improve with 100% oxygen suggests:', '["Pneumonia", "Right-to-Left Cardiac Shunt (e.g., Tetralogy of Fallot)", "Asthma", "Anemia"]', 1, 'This is a "True Shunt."'),
    (v_topic_id, '175: "Sudden Death" in a young athlete during a game is most commonly:', '["MI", "Hypertrophic Cardiomyopathy (HOCM)", "Pneumothorax", "Dehydration"]', 1, 'The thickened septum can cause dynamic outflow obstruction and lethal arrhythmias.'),
    (v_topic_id, '176: "Palpitations" that feel like a "Drumming" or "Racing" in the neck (Frog sign) are seen in:', '["Atrial Fibrillation", "AVNRT (Supraventricular Tachycardia)", "Sinus Tachycardia", "PVCs"]', 1, 'The atria and ventricles contract simultaneously against closed valves, causing venous pulsation.'),
    (v_topic_id, '177: "Chest Pain" in a patient with "Cocaine" use is often due to:', '["Pneumonia", "Coronary artery vasospasm and increased O2 demand", "GERD", "Asthma"]', 1, 'Cocaine also increases the risk of aortic dissection.'),
    (v_topic_id, '178: "Syncope" that is preceded by "Palpitations" is more likely to be _____ than vasovagal.', '["Psychogenic", "Cardiac (arrhythmia-induced)", "Epileptic", "Orthostatic"]', 1, 'A high-yield red flag.'),
    (v_topic_id, '179: "Orthostatic Hypotension" is defined as a drop in systolic BP of _____ or diastolic BP of _____ after standing:', '["10 / 5 mmHg", "20 / 10 mmHg", "50 / 20 mmHg", "5 / 2 mmHg"]', 1, 'Commonly due to dehydration or autonomic dysfunction (diabetes).'),
    (v_topic_id, '180: "Dyspnea" + "Dry Cough" + "Velcro-like fine crackles" on lung exam is:', '["CHF", "Interstitial Lung Disease (e.g., Idiopathic Pulmonary Fibrosis)", "Pneumonia", "Asthma"]', 1, 'Classic physical exam finding for fibrosis.'),
    (v_topic_id, '181: "Chest Pain" + "Hamman''s Sign" + "History of forceful vomiting" is:', '["MI", "Boerhaave Syndrome (Esophageal Rupture)", "Mallory-Weiss tear", "GERD"]', 1, 'Mallory-Weiss is only a mucosal tear (bleeding); Boerhaave is a full-thickness rupture (air/infection).'),
    (v_topic_id, '182: A "Hyper-resonant" chest with "Absent breath sounds" and "Tracheal deviation" is:', '["Normal Pneumothorax", "Tension Pneumothorax (emergency)", "Pleural effusion", "Pneumonia"]', 1, 'The pressure in the pleural space is pushing the mediastinum to the opposite side.'),
    (v_topic_id, '183: "Beck''s Triad" (Hypotension, JVD, and Muffled heart sounds) is diagnostic for:', '["MI", "Cardiac Tamponade", "PE", "Pneumonia"]', 1, 'The heart is compressed by fluid in the pericardial sac.'),
    (v_topic_id, '184: "Electrical Alternans" on ECG (alternating height of QRS complexes) is a sign of:', '["MI", "Large Pericardial Effusion/Tamponade", "SVT", "Heart block"]', 1, 'The heart is literally "swinging" back and forth in the fluid-filled sac.'),
    (v_topic_id, '185: "Right Ventricular Lift/Heave" felt at the left sternal border suggests:', '["Normal heart", "Right Ventricular Hypertrophy (e.g., from Pulmonary HTN)", "LVH", "Mitral Valve Prolapse"]', 1, 'Also seen in severe COPD (Cor Pulmonale).'),
    (v_topic_id, '186: "Thrills" felt on the chest wall are:', '["A sign of joy", "Palpable murmurs (Grade 4 or higher)", "Normal", "Heart beats"]', 1, 'Indicates significant turbulent blood flow.'),
    (v_topic_id, '187: "Chest Pain" that is "Relieved by Nitroglycerin" was traditionally used to diagnose angina, but can also relieve:', '["PE", "Esophageal Spasm", "Pneumonia", "Pneumothorax"]', 1, 'Nitro is not a specific test for cardiac pain.'),
    (v_topic_id, '188: "Cough" that is worse at night and after exercise in a child is often:', '["Croup", "Asthma", "Pneumonia", "GERD"]', 1, 'Asthma often presents as a "cough-variant" in children.'),
    (v_topic_id, '189: "Barking" cough (like a seal) in a child with "Inspiratory stridor" is:', '["Asthma", "Croup (Laryngotracheobronchitis)", "Epiglottitis", "Pneumonia"]', 1, 'Caused by parainfluenza virus.'),
    (v_topic_id, '190: "Drooling" and "Tripod position" in a child with a sore throat is:', '["Strep throat", "Epiglottitis (medical emergency)", "Croup", "Common cold"]', 1, 'The child cannot swallow secretions and is trying to keep the airway open.'),
    (v_topic_id, '191: "Thumbprint Sign" on a lateral neck X-ray is classic for:', '["Croup", "Epiglottitis", "Foreign body", "Tonsillitis"]', 1, 'Reflects the swollen, inflamed epiglottis.'),
    (v_topic_id, '192: "Steeple Sign" on a frontal neck X-ray is classic for:', '["Epiglottitis", "Croup", "Foreign body", "Asthma"]', 1, 'Reflects subglottic narrowing.'),
    (v_topic_id, '193: "Dyspnea" + "History of Heavy Smoking" + "Flattened diaphragms on CXR" is:', '["Pneumonia", "COPD (Emphysema)", "CHF", "PE"]', 1, 'Reflects hyperinflation of the lungs.'),
    (v_topic_id, '194: "Palpitations" that started after a "Heavy weekend of drinking alcohol" is:', '["MI", "Holiday Heart Syndrome (Atrial Fibrillation)", "Stroke", "Diabetes"]', 1, 'Alcohol is a common trigger for AFib.'),
    (v_topic_id, '195: "Chest Pain" that radiates to the "Jaw" or "Teeth" is most likely:', '["Toothache", "Myocardial Ischemia (Angina/MI)", "GERD", "Bell''s palsy"]', 1, 'Referred pain from the heart.'),
    (v_topic_id, '196: "Dyspnea" that is sudden in a tall, thin young man after lifting something is:', '["MI", "Spontaneous Pneumothorax", "Asthma", "Pneumonia"]', 1, 'Rupture of a subpleural bleb.'),
    (v_topic_id, '197: "Syncope" while "Straining to have a bowel movement" is:', '["Cardiac", "Vasovagal (Defecation syncope)", "Stroke", "Diabetes"]', 1, 'The Valsalva maneuver reduces venous return and triggers a reflex.'),
    (v_topic_id, '198: "Chest Pain" + "Friction Rub" heard on auscultation is diagnostic of:', '["Pneumonia", "Pericarditis (or Pleuritis)", "Heart failure", "Murmur"]', 1, 'Sounds like "sandpaper" or "leather rubbing together."'),
    (v_topic_id, '199: "Cough" and "Wheezing" that is worse in the workplace but improves on weekends is:', '["COPD", "Occupational Asthma", "Pneumonia", "Bronchitis"]', 1, 'Crucial to take an occupational history.'),
    (v_topic_id, '200: A "Cannon a-wave" in the JVP is a sign of:', '["Atrial Fibrillation", "Third-degree Heart Block (Atrioventricular Dissociation)", "Mitral Stenosis", "Tricuspid Regurgitation"]', 1, 'The atrium contracts against a closed tricuspid valve.');
